--trigger de atualizaçao
create or alter trigger G_TR_CONNECT_1 on connect
as
declare variable V_UF varchar(10);
declare variable V_DROP varchar(500);
begin
  if (current_date >= cast('2026-01-01' as date)) then
  begin
    select trim(C.VALOR)
    from G_CONFIG C
    inner join G_CONFIG_GRUPO G on C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
    where G.SISTEMA_ID = 5
      and c.secao = 'CARTORIO'
      and c.nome = 'UF'
    into :v_uf;
    
    if (:v_uf = 'GO') then
    begin
      UPDATE G_CONFIG SET VALOR = '50031' WHERE NOME = 'PERIODO_PADRAO';
      UPDATE G_CONFIG SET VALOR = '50031' WHERE NOME = 'TABELA_PADRAO_CALCULO_RAPIDO';
    end
  end
end